(788943, 86230, 17279, '<td valign="top">Very nicely composed...the lighting and point of view make this one extraordinary.</td>', 'Very nicely composed...the lighting and point of view make this one extraordinary.', '2004-07-01 03:29:49.000000', NULL, 1),
(788945, 86651, 17279, '<td valign="top">Very nicely done!</td>', 'Very nicely done!', '2004-07-01 03:30:16.000000', NULL, 1),
(788946, 86553, 22480, '<td valign="top">Wasn''t this in last week''s challenge too? I like this one better.</td>', 'Wasn''t this in last week''s challenge too? I like this one better.', '2004-07-01 03:30:28.000000', NULL, 1),
(788947, 86631, 17279, '<td valign="top">Eggstraordinary :)</td>', 'Eggstraordinary :)', '2004-07-01 03:30:46.000000', NULL, 1),
