(791814, 86227, 17279, '<td valign="top">very cool... perhaps a somewhat tighter crop?</td>', 'very cool... perhaps a somewhat tighter crop?', '2004-07-02 03:50:32.000000', NULL, 1),
(791815, 86612, 17279, '<td valign="top">Well, this just doesn''t say "extraordinary" too me.  Although I find the message somewhat distasteful, I won''t vote it low on that basis.  I certainly hope this was just a good makeup job.</td>', 'Well, this just doesn''t say "extraordinary" too me.  Although I find the message somewhat distasteful, I won''t vote it low on that basis.  I certainly hope this was just a good makeup job.', '2004-07-02 03:52:03.000000', NULL, 1),
(791816, 86639, 17279, '<td valign="top">What a great character for a subject.  I would crop a bit tighter on the face and headress(?)...such great lines there.  Perhaps a tad less contrast as well.</td>', 'What a great character for a subject.  I would crop a bit tighter on the face and headress(?)...such great lines there.  Perhaps a tad less contrast as well.', '2004-07-02 03:53:19.000000', NULL, 1),
(791817, 86725, 17279, '<td valign="top">Nice wide-angle view.  Too bad about the sky though.</td>', 'Nice wide-angle view.  Too bad about the sky though.', '2004-07-02 03:53:54.000000', NULL, 1),
(791818, 86424, 17279, '<td valign="top">Nice image...good job on the effects.</td>', 'Nice image...good job on the effects.', '2004-07-02 03:54:33.000000', NULL, 1),
(791819, 86425, 17279, '<td valign="top">Truly extraordinary!  Focus seems a bit off though.</td>', 'Truly extraordinary!  Focus seems a bit off though.', '2004-07-02 03:55:23.000000', NULL, 1),
