(791822, 86486, 17279, '<td valign="top">Wow, what great clouds!</td>', 'Wow, what great clouds!', '2004-07-02 04:00:13.000000', NULL, 1),
(791843, 86639, 19952, '<td valign="top">Really stunning shot that shows a lot of depth character - one of my favorites in the challenge. Shame another person took such a similar photo, but that can''t lower the score for such an excellent shot. Great job!</td>', 'Really stunning shot that shows a lot of depth character - one of my favorites in the challenge. Shame another person took such a similar photo, but that can''t lower the score for such an excellent shot. Great job!', '2004-07-02 04:52:38.000000', NULL, 1),
(791844, 86615, 19952, '<td valign="top">Beautiful shot with great color and nice composition. Focus is just a bit soft, but it''s still one of the best shots in the challenge. Nice job!</td>', 'Beautiful shot with great color and nice composition. Focus is just a bit soft, but it''s still one of the best shots in the challenge. Nice job!', '2004-07-02 04:54:26.000000', NULL, 1),
(791845, 86211, 23016, '<td valign="top">Good idea! Great colors,.... but the top of the tree...</td>', 'Good idea! Great colors,.... but the top of the tree...', '2004-07-02 04:59:51.000000', NULL, 1),
(791848, 86634, 19952, '<td valign="top">Excellent shot with great depth and clarity. Bet you sell a ton of these. ;-)</td>', 'Excellent shot with great depth and clarity. Bet you sell a ton of these. ;-)', '2004-07-02 05:09:22.000000', NULL, 1),
(791849, 86317, 19952, '<td valign="top">Wow - now that is extraordinary. This is an absolutely beautiful photo with perfect color and clarity. Great job!</td>', 'Wow - now that is extraordinary. This is an absolutely beautiful photo with perfect color and clarity. Great job!', '2004-07-02 05:18:59.000000', NULL, 1),
(791853, 86458, 19952, '<td valign="top">This is such a great shot. It''s amazing that the water is so smooth. Once the contest is over, you might want to clean up a couple of those stray spots, but this photo is really excellent regardless. Nice job!</td>', 'This is such a great shot. It''s amazing that the water is so smooth. Once the contest is over, you might want to clean up a couple of those stray spots, but this photo is really excellent regardless. Nice job!', '2004-07-02 05:31:38.000000', NULL, 1),
