(796941, 86230, 164, '<td valign="top">Good use of light. The road does make the eye travel towards the light.</td>', 'Good use of light. The road does make the eye travel towards the light.', '2004-07-05 19:56:59.000000', NULL, 1),
(796958, 86525, 6520, '<td valign="top">Yikes</td>', 'Yikes', '2004-07-05 20:40:51.000000', NULL, 1),
